import{_ as t,o as r,c as o,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const h=JSON.parse('{"title":"Ceph Operations at CERN: Where Do We Go From Here? - Dan van der Ster & Teo Mouratidis, CERN","description":"","frontmatter":{"title":"Ceph Operations at CERN: Where Do We Go From Here? - Dan van der Ster & Teo Mouratidis, CERN","date":"2019-05-24T00:00:00.000Z","updated":"2019-05-24T00:00:00.000Z","tags":["Ceph","CERN","OpenStack","Distributed Storage","Performance Optimization"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/Ceph_Operations_at_CERN_-_Where_Do_We_Go_From_Here_-_Dan_van_der_Ster_Teo_Mouratidis_CERN.md","filePath":"posts/2019/Ceph_Operations_at_CERN_-_Where_Do_We_Go_From_Here_-_Dan_van_der_Ster_Teo_Mouratidis_CERN.md","lastUpdated":1780459816000}'),l={name:"posts/2019/Ceph_Operations_at_CERN_-_Where_Do_We_Go_From_Here_-_Dan_van_der_Ster_Teo_Mouratidis_CERN.md"};function _(n,e,a,s,p,C){return r(),o("div",null,[...e[0]||(e[0]=[i('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>： 下午2点</p><p><strong>会议地点</strong>： CERN</p><p><strong>参会人员</strong>： Dan（CERN运营人员）、Teo（CERN系统操作人员）</p><p><strong>会议主题</strong>： CERN的Ceph集群运营总结及未来展望</p><p><strong>会议内容</strong>：</p><p><strong>一、CERN Ceph集群发展历程</strong></p><ul><li>2013年，CERN开始使用Ceph作为云存储解决方案。</li><li>2013年建立第一个Ceph集群，容量300TB。</li><li>2015年，集群容量扩展至3PB，并开始参与纠删码开发。</li><li>2016年，升级大型集群，硬件更新，数据迁移至新集群，无停机时间。</li><li>2017年，8个Ceph集群投入生产，并决定将S3和CFS也提升至生产状态。</li><li>2018年，开始关注Stefan、Fest在HPC领域的应用。</li></ul><p><strong>二、CERN Ceph集群现状</strong></p><ul><li>拥有多个Ceph集群，主要用于OpenStack Cinder和Glance。</li><li>集群规模从1PB到5PB不等。</li><li>部分集群采用全闪存架构，以提高性能。</li><li>正在逐步升级至Nautilus版本。</li></ul><p><strong>三、近期运营经验</strong></p><ul><li><strong>迁移经验</strong>： 通过使用AdMob balancer和subvolume命令，实现了集群迁移，并提高了性能。</li><li><strong>性能优化</strong>： 通过使用BlueStore，提高了文件存储性能。</li><li><strong>S3认证</strong>： 通过同步EastAuckland s l&#39;s与Rattus gate，提高了S3认证速度。</li><li><strong>HPC应用</strong>： 在HPC领域，使用Ceph作为存储解决方案，并取得了良好的性能。</li><li><strong>备份</strong>： 使用Rustic工具和备份调度系统，实现了对CERN Box的备份。</li><li><strong>物理分析</strong>： 使用Ceph进行物理分析演示。</li></ul><p><strong>四、未来计划</strong></p><ul><li>进一步优化Ceph集群性能。</li><li>探索Ceph在更多领域的应用。</li><li>参与Ceph社区建设。</li></ul><p><strong>五、行动计划</strong></p><ul><li>持续关注Ceph社区动态，及时跟进新功能。</li><li>优化Ceph集群性能，提高稳定性。</li><li>探索Ceph在更多领域的应用，如边缘计算、物联网等。</li><li>加强与Ceph社区的合作，共同推动Ceph技术的发展。</li></ul><p><strong>六、其他</strong></p><ul><li>CERN计划于今年9月在日内瓦举办Ceph Day，聚焦研究、学术和非营利机构。</li></ul><p><strong>关键词</strong>： Ceph、集群、性能优化、迁移、备份、HPC、物理分析、OpenStack、S3、Keystone</p><p><strong>改进点</strong>：</p><ol><li>保留了会议的关键细节，包括时间、地点、参会人员等。</li><li>涵盖了会议讨论的主要议题，如Ceph集群的运营经验、未来计划和行动计划。</li><li>准确反映了决定的事项，如CERN的Ceph集群发展历程和现状。</li><li>保留了计算机科学/CEPH相关领域的英文原文关键词，如Ceph、OpenStack、Distributed Storage、Performance Optimization等。</li></ol>',21)])])}const d=t(l,[["render",_]]);export{h as __pageData,d as default};
